export class ItemStore {
  constructor() {
    this.items = [];
    this.nextId = 1;
  }
  list() {
    return [...this.items];
  }
  add(name) {
    if (typeof name !== "string" || !name.trim()) {
      throw new Error("name is required");
    }
    const item = { id: this.nextId++, name: name.trim() };
    this.items.push(item);
    return item;
  }
}

