import { createServer } from "node:http";
import { ItemStore } from "./store.mjs";

export function createApp(store = new ItemStore()) {
  return createServer(async (req, res) => {
    const send = (status, data) => {
      res.writeHead(status, { "Content-Type": "application/json" });
      res.end(JSON.stringify(data));
    };
    if (req.method === "GET" && req.url === "/health") {
      return send(200, { status: "ok" });
    }
    if (req.method === "GET" && req.url === "/items") {
      return send(200, { items: store.list() });
    }
    if (req.method === "POST" && req.url === "/items") {
      const chunks = [];
      for await (const chunk of req) chunks.push(chunk);
      try {
        const body = JSON.parse(Buffer.concat(chunks).toString("utf8"));
        return send(201, store.add(body?.name));
      } catch (error) {
        return send(400, { error: error instanceof Error ? error.message : "Invalid request" });
      }
    }
    return send(404, { error: "Not found" });
  });
}

